sys_security_acl.script:
var admin_permission = gs.hasRole('x_hccc_hoc_ohs.admin');
var advisor_permission = gs.hasRole('x_hccc_hoc_ohs.advisor');
var admin_or_advisor_permission = (admin_permission || advisor_permission);

var report_type = current.pdf_template.sys_id;
var lab_1058 = (String(report_type) === '2306fd9c8774ad5050d2eca73cbb3500' || String(report_type) === '55703d708701a99450d2eca73cbb3566');
var committee_permission = (gs.hasRole('x_hccc_hoc_ohs.committee') && lab_1058);

var current_user = gs.getUserID();
var report_building = current.inc_location;

answer = new x_hccc_hoc_ohs.HoCOHSMUtils().getCommitteeRecordPermissions(admin_or_advisor_permission, committee_permission, current_user, report_building);
